mapper.select:
SELECT id AS userId, nickname, avatar_url AS avatarUrl, openid, status, last_login_ip AS lastLoginIp, last_login_at AS lastLoginAt, created_at AS createdAt FROM pet_snack_user WHERE deleted = 0 AND status = #{status}
AND (nickname LIKE CONCAT('%', #{keyword}, '%') OR openid LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY id DESC LIMIT #{offset}, #{limit}

SELECT o.id AS orderId, o.order_no AS orderNo, o.user_id AS userId, u.nickname, u.avatar_url AS avatarUrl, o.status, o.payment_status AS paymentStatus, o.receiver_name AS receiverName, o.receiver_phone AS receiverPhone, o.pay_amount AS payAmountYuan, o.total_quantity AS totalQuantity, o.transaction_id AS transactionId, o.paid_at AS paidAt, o.created_at AS createdAt FROM pet_snack_order o LEFT JOIN pet_snack_user u ON u.id = o.user_id AND u.deleted = 0 WHERE o.deleted = 0 AND o.status = #{status}
AND (o.order_no LIKE CONCAT('%', #{keyword}, '%') OR o.receiver_name LIKE CONCAT('%', #{keyword}, '%') OR o.receiver_phone LIKE CONCAT('%', #{keyword}, '%') OR u.nickname LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY o.id DESC LIMIT #{offset}, #{limit}
